const items = $input.all();
const cleanedData = [];

function cleanRestoName(raw) {
  if (!raw) return '';
  let n = raw.split('|')[0].split('@')[0].trim();
  n = n.replace(/\s*-\s*Kandahar Street/gi, '');
  n = n.replace(/\((.*?)\)/g, '').trim();
  n = n.replace(/Restaurant|Singapore|Malaysia|SG|KL/gi, '').trim();
  return n || raw.trim();
}

let targetCountry = 'Malaysia';
let targetCity = 'Kuala Lumpur';
let queueId = null;

try {
  const q = $('2. Cek Antrian Negara di Supabase').item.json;
  targetCountry = q.country || 'Malaysia';
  targetCity = q.city_or_region || 'Kuala Lumpur';
  queueId = q.queue_id || null;
} catch (e) {}

for (const item of items) {
  const row = item.json;
  if (!row.name && !row.title) continue;

  const rawName = row.name || row.title;
  const cleanName = cleanRestoName(rawName);

  const socials = row.social_links || {};
  const instagram = socials.instagram || row['social_links/instagram'] || null;
  const facebook = socials.facebook || row['social_links/facebook'] || null;
  const tiktok = socials.tiktok || row['social_links/tiktok'] || null;
  const linkedin = socials.linkedin || row['social_links/linkedin'] || null;

  const email = (row.email && typeof row.email === 'string' && row.email.includes('@')) 
    ? row.email.trim().toLowerCase() 
    : null;

  const phone = row.phone ? String(row.phone).trim() : null;

  cleanedData.push({
    json: {
      queue_id: queueId,
      place_id: row.place_id || `temp_${cleanName.replace(/\s+/g, '_')}`,
      name: rawName,
      clean_name: cleanName,
      category: row.category || 'Indonesian restaurant',
      country: row.country || targetCountry,
      city: row.city || targetCity,
      address: row.address || '',
      latitude: row.latitude ? parseFloat(row.latitude) : null,
      longitude: row.longitude ? parseFloat(row.longitude) : null,
      maps_url: row.maps_url || row.url || null,
      phone: phone,
      email: email,
      email_source: row.email_source || (email ? 'apify_scraper' : null),
      website: row.website || null,
      cms: row.cms || null,
      has_contact_form: row.has_contact_form === true || row.has_contact_form === 'true',
      instagram_url: instagram,
      facebook_url: facebook,
      tiktok_url: tiktok,
      linkedin_url: linkedin,
      rating: row.rating ? parseFloat(row.rating) : 4.5,
      review_count: row.review_count ? parseInt(row.review_count, 10) : 0,
      contactability_score: row.contactability_score ? parseInt(row.contactability_score, 10) : (email ? 85 : 50),
      lead_priority: (row.lead_priority || (email ? 'hot' : 'warm')).toLowerCase(),
      status_email: 'pending',
      status_whatsapp: 'pending'
    }
  });
}

return cleanedData;
